for i in range(5):
    if i == 3:
        break
    print(i)

for i in range(2):
    for j in range(2):
        print(i, j)

result = []
for x in range(5):
    result.append(x * 2)

def generator():
    for i in range(3):
        yield i
    else:
        print("Loop completed")

gen = generator()
for num in gen:
    print(num)
